<?php namespace App\Http\Controllers; use App\Models\{Job,Inspection,DamageRecord,InspectionPhoto}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class InspectionController extends Controller {public function edit(Job $job){$inspection=$job->inspection ?: new Inspection(['job_id'=>$job->id]);$job->load('vehicle','customer');return view('jobs.inspection',compact('job','inspection'));} public function update(Request $r,Job $job){$d=$r->validate(['mileage'=>'nullable|integer','fuel_level'=>'nullable|integer|min:0|max:100','exterior_condition'=>'nullable','interior_condition'=>'nullable','tyre_condition'=>'nullable','wheel_condition'=>'nullable','glass_condition'=>'nullable','lights_condition'=>'nullable','dashboard_warnings'=>'nullable','findings'=>'nullable','recommendations'=>'nullable','damage_type'=>'nullable','damage_location'=>'nullable','damage_severity'=>'nullable','damage_description'=>'nullable','photo'=>'nullable|image|max:5120']);$inspection=Inspection::updateOrCreate(['job_id'=>$job->id],collect($d)->except(['damage_type','damage_location','damage_severity','damage_description','photo'])->toArray());if($d['damage_type']??null)DamageRecord::create(['job_id'=>$job->id,'type'=>$d['damage_type'],'location'=>$d['damage_location']??null,'severity'=>$d['damage_severity']??'minor','description'=>$d['damage_description']??null]);if($r->hasFile('photo')){ $path=$r->file('photo')->store('inspections','public');InspectionPhoto::create(['job_id'=>$job->id,'category'=>'inspection','path'=>$path,'uploaded_by'=>auth()->id()]);}$job->update(['status'=>'inspection_completed']);return redirect()->route('jobs.show',$job)->with('success','Inspection completed.');}}
